SUBJECTS_AND_CHAPTERS = [
    ('Physics', PHYSICS),
    ('Chemistry', CHEMISTRY),
    ('Mathematics', MATHEMATICS),
    ('Biology', BIOLOGY),
    ('Computer Science', COMPUTER_SCIENCE),
    ('English', ENGLISH),
]


def get_or_create_subject(db, name: str, creator_id: str) -> models.Subject:
    existing = db.execute(select(models.Subject).where(models.Subject.name == name)).scalar_one_or_none()
    if existing:
        return existing
    subject = models.Subject(name=name, created_by=creator_id)
    db.add(subject)
    db.commit()
    db.refresh(subject)
    return subject


def get_or_create_chapter(db, subject: models.Subject, name: str, position: int) -> models.Chapter:
    existing = db.execute(
        select(models.Chapter).where(models.Chapter.subject_id == subject.id, models.Chapter.name == name)
    ).scalar_one_or_none()
    if existing:
        return existing
    chapter = models.Chapter(subject_id=subject.id, name=name, position=position)
    db.add(chapter)
    db.commit()
    db.refresh(chapter)
    return chapter


def add_chapter_questions(
    db, subject: models.Subject, chapter: models.Chapter, creator_id: str, items: list[tuple]
) -> int:
    existing_questions = {
        q.text: q
        for q in db.execute(select(models.Question).where(models.Question.subject_id == subject.id)).scalars()
    }
    added = 0
    for text, options, correct_index, explanation in items:
        existing = existing_questions.get(text)
        if existing:
            if existing.chapter_id is None:
                existing.chapter_id = chapter.id
                db.add(existing)
                db.commit()
            continue
        question = models.Question(
            subject_id=subject.id, chapter_id=chapter.id, created_by=creator_id, text=text, explanation=explanation
        )
        question.options = [
            models.Option(text=opt, position=i, is_correct=(i == correct_index))
            for i, opt in enumerate(options)
        ]
        db.add(question)
        added += 1
    db.commit()
    return added


def main() -> None:
    db = SessionLocal()
    try:
        creator = db.execute(select(models.User)).scalars().first()
        if not creator:
            creator = models.User(
                name="Demo User", email="demo@example.com", password_hash=hash_password("password123")
            )
            db.add(creator)
            db.commit()
            db.refresh(creator)
            print("No existing user found -- created demo@example.com (password: password123).")

        for name, groups in SUBJECTS_AND_CHAPTERS:
            subject = get_or_create_subject(db, name, creator.id)
            added_total = 0
            for position, (chapter_name, items) in enumerate(groups):
                chapter = get_or_create_chapter(db, subject, chapter_name, position)
                added_total += add_chapter_questions(db, subject, chapter, creator.id, items)
            total = len(
                db.execute(select(models.Question).where(models.Question.subject_id == subject.id)).scalars().all()
            )
            print(f"{name}: added {added_total} new questions across {len(groups)} chapters ({total} total now).")
    finally:
        db.close()


if __name__ == "__main__":
    main()
